// Own properties on a FUNCTION VALUE reached through the checked-dynamic
// path. `box`'s parameter and return are untyped, so `f` below is a dyn
// value at runtime — a SCR_DYN_FUNC box when a function is passed — and
// `f.k = v` is the dyn keyed write.
//
// The load-bearing case is `g`: a SECOND box of the SAME function. The
// property table hangs off the closure, not the box, so JS's "one
// function object" holds across boundary crossings. If the table lived on
// the box, `g.kind` would answer undefined here and Node would say
// "codec".
'use strict';

function box(v) { return v; }

function target(a) { return "T" + a; }

function run() {
    var out = [];
    var f = box(target);

    f.kind = "codec";
    f.count = 3;

    out.push(f.kind);                 // codec
    out.push(String(f.count));        // 3

    // Own-property presence is what protobufjs's generated encode guards
    // EVERY field with, so it has to see the write.
    out.push(String(Object.hasOwn(f, "kind")));  // true
    out.push(String(Object.hasOwn(f, "nope")));  // false
    out.push(String(Object.hasOwn(f, "name")));  // true

    // `in` over the same receiver.
    out.push(String("count" in f));              // true

    // Object.keys lists the assigned properties and NOT the built-ins.
    out.push(Object.keys(f).join(","));          // kind,count

    // Object.assign copies the same set Object.keys lists.
    var copy = Object.assign({}, f);
    out.push(copy.kind + "/" + copy.count);      // codec/3

    // A second box of the same function value sees the same properties.
    var g = box(target);
    out.push(String(g.kind));                    // codec

    // A later write through the second box is visible through the first.
    g.count = 9;
    out.push(String(f.count));                   // 9

    // A function value with NO assigned properties still lists none.
    var bare = box(function () { return 0; });
    out.push(Object.keys(bare).join(",") + "#");  // #
    out.push(String(Object.hasOwn(bare, "kind")));  // false

    // A function-VALUED property, called through the receiver — pbjs's
    // whole API shape (`Codec.encode(msg)`). Dispatch finds it in the
    // same table and runs it with the receiver bound.
    f.enc = function (x) { return "E" + x; };
    out.push(f.enc(5));                          // E5

    // The value is still callable, and still a function.
    out.push(f(1));                              // T1
    out.push(typeof f);                          // function

    return out.join("|");
}

module.exports = { run: run };
